{"script":"() => {
  // Close any open overlay/dialog
  const closeButtons = document.querySelectorAll('[aria-label*="Close" i], [aria-label*="close" i], button[class*="close" i], button[class*="dismiss" i]');
  for (const btn of closeButtons) {
    try { btn.click(); } catch (e) {}
  }
  // Also try removing any overlay elements
  const overlays = document.querySelectorAll('[role="dialog"], [aria-modal="true"], .modal, .overlay');
  overlays.forEach(o => o.remove());
  return 'overlay closed';
}"}

