{"script":"() => {
  // Try to find the page text including Pro Max info
  const body = document.body.innerText;
  // Find lines with 'Pro' or pricing
  const lines = body.split('\n').filter(line => 
    line.includes('Pro') || line.includes('Pro Max') || 
    line.includes('$') || line.includes('inch') || line.includes('display') ||
    line.includes('Screen')
  ).slice(0, 100);
  return lines.join('\n');
}"}

